INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','catedral','Catedral de Santa María de Regla (La Pulchra Leonina)','Obra cumbre del gótico clásico de los siglos XIII y XIV de influencia francesa, declarada Monumento Nacional, erigida con una suntuosa sillería caliza de Boñar de tonalidades cálidas que destaca por la desmaterialización de sus muros cortina en favor de un majestuoso conjunto de 134 ventanales y 3 rosetones de vidrieras medievales polícromas únicas en el mundo, flanqueada en el exterior por dos torres caladas exentas y un espectacular Pórtico de la Virgen Blanca tallado con exquisita minuciosidad escultórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','iglesia','Real Colegiata de San Isidoro','Magna basílica románica de los siglos XI y XII consagrada como el hito arquitectónico más importante del románico pleno peninsular que custodia el Panteón de los Reyes de León, un espacio subterráneo denominado la Capilla Sixtina del arte románico por conservar intactos sus frescos murales del siglo XII policromados sobre mortero de cal, sustentados por columnas exentas con capiteles historiados de sillería caliza labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','monumento','Hostal de San Marcos','Monumental monasterio y antiguo hospital de peregrinos fundado en el siglo XVI por orden del rey Fernando el Católico que constituye la obra maestra del estilo plateresco y renacentista español, cuya larguísima','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','palacio','Palacio de los Guzmanes','Palacio señorial renacentista del siglo XVI proyectado por el célebre arquitecto Rodrigo Gil de Hontañón para la familia de los Guzmanes que presenta una fachada monumental de cantería caliza con arquerías altas platerescas, balconadas de hierro forjado apoyadas sobre ménsulas molduradas y un suntuoso patio interior porticado con columnas jónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','palacio','Casa Botines (Palacio de los Botines)','Espectacular edificio de estilo neogótico y modernista diseñado entre 1891 y 1892 por el arquitecto catalán Antoni Gaudí que destaca por su planta trapezoidal erigida con muros de sillería de granito gris de El Bierzo bien escuadrados, rematada por cuatro torres cilíndricas angulares coronadas por chapiteles de pizarra negra y una portada principal protegida por una escultura de San Jorge y el dragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','monumento','Muralla Romana y Medieval de León','Recinto amurallado de origen romano (siglo III d.C.) levantado por la Legio VII Gemina con potentes muros de mampostería de cuarcita y cantos rodados compactados con mortero hidráulico, reconstruido sustancialmente en la Baja Edad Media con sillares calcáreos y jalonado por una treintena de cubos semicirculares exentos conocidos popularmente como "los Caños".','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='34120';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','catedral','Catedral de San Antolín (La Bella Desconocida)','Magna catedral gótica construida principalmente entre los siglos XIV y XVI sobre vestigios visigodos y románicos empleando una suntuosa sillería caliza de Hontoria que destaca por la inmensidad de su interior de tres naves con bóvedas de crucería estrellada gótico-flamígeras, albergando en su presbiterio el fastuoso retablo mayor plateresco con esculturas de Juan de de Juni y pinturas de Juan de de Flandes, la cripta visigoda de San Antolín del siglo VII erigida con arcos de herradura de piedra rústica y el célebre trascoro tardogótico esculpido con exquisita minuciosidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Iglesia de San Miguel','Monumental templo gótico del siglo XIII levantado en sillería caliza bien escuadrada que destaca por su imponente torre campanario de carácter defensivo calada con grandes ventanales apuntados y rematada por almenas y un chapitel calado, cuyo interior basilical conserva restos de pinturas murales góticas y un retablo renacentista de gran mérito artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Monasterio de San Pablo','Complejo conventual dominico de los siglos XIV a XVI cuya iglesia destaca por su majestuosa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','iglesia','Iglesia de San Juan Bautista (San Juan de Baños Trasladada)','Pequeño templo románico rural del siglo XII que fue rescatado piedra a piedra de su emplazamiento original inundado y reconstruido en los jardines de la Huerta de Guadián empleando sus sillares originales areniscos, sirviendo como un hito expositivo de la arquitectura medieval de la cuenca del Carrión.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='22125';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','catedral','Catedral de Santa María de la Asunción','Magna catedral gótica construida principalmente entre los siglos XIII y XVI sobre vestigios románicos y una antigua mezquita aljama, utilizando una suntuosa sillería caliza prepirenaica que destaca exteriormente por su gran fachada-retablo con una espectacular portada de arcos apuntados doblados y un alero de madera tallada de gran porte, cuyo interior basilical cobija el monumental retablo mayor exento esculpido en mármol de alabastro calizo por Damián Forment.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','iglesia','Monasterio de San Pedro el Viejo','Joya universal e hito absoluto del románico pleno aragonés del siglo XII, declarado Monumento Nacional, erigido con una excelente y recia sillería bien escuadrada que destaca por poseer un claustro reglar de planta trapezoidal cuyos capiteles historiados muestran una legendaria colección de motivos bíblicos tallados por el Maestro de San Juan de la Peña, albergando en su iglesia las capillas sepulcrales donde reposan los reyes de Aragón Alfonso I el Batallador y Ramiro II el Monje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','palacio','Palacio Real de los Reyes de Aragón (Museo de Huesca)','Espectacular e hito de la arquitectura civil de estilo románico tardío (siglo XII) que conserva dependencias históricas del linaje real, tales como la Sala de la Campana o el Salón del Trono erigidos con gruesos muros de sillería caliza y bóvedas de crucería, célebre en la historia peninsular por la leyenda de la Campana de Huesca.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='26089';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','catedral','Concatedral de Santa María de la Redonda','Magna basílica de los siglos XV al XVIII que destaca universalmente por su espectacular fachada occidental barroca de líneas clasicistas francesas proyectada por Juan de Ancheta en estilo retablo, flanqueada por las célebres y esbeltas "Torres Gemelas" caladas con hornacinas y pináculos, cuyo interior cobija un espectacular calvario al óleo atribuido a Miguel Ángel Buonarroti.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','iglesia','Iglesia de Santiago el Real','Templo monumental gótico del siglo XVI edificado sobre vestigios medievales en pleno Camino de Santiago Francés utilizando excelente cantería de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','iglesia','Iglesia de San Bartolomé','Templo románico de transición y gótico clásico del siglo XIII erigido con excelente sillería arenisca dorada bien escuadrada que destaca por poseer la única portada gótica monumental de Logroño, un espectacular tapiz pétreo esculpido con arcos apuntados profusamente ornamentados que cobijan relieves de la vida del santo y marcas de cantero medievales únicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','monumento','Yacimiento Romano de Varea (Varia)','Área arqueológica consolidada que conserva los cimientos perimetrales de piedra rústica, pavimentos de opus signinum, alfares y estructuras habitacionales de la antigua ciudad romana de los siglos I al IV d.C., catalogada como un hito científico e histórico para el estudio de la romanización del valle del Ebro.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='42173';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Monasterio de San Juan de Duero','Joya excepcional del románico universal del siglo XII levantada en sillería caliza por la Orden de los Hospitalarios a orillas del Duero, célebre por su espectacular claustro a cielo abierto cuyos arcos entrelazados, túmidos y apuntados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','catedral','Concatedral de San Pedro','Magna basílica del gótico plateresco iniciada en el siglo XVI en excelente cantería caliza regular, que destaca por su espacioso interior de tres naves a igual altura con bóvedas de crucería estrellada y, de forma sobresaliente, por conservar el monumental claustro románico del siglo XII del antiguo cenobio con arquerías de medio punto profusamente historiadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Iglesia de Santo Domingo','Obra cumbre de la escultura románica española de finales del siglo XII construida en sillería caliza, célebre internacionalmente por su fachada monumental cuya portada presenta cuatro arquivoltas profusamente labradas con escenas bíblicas, un gran pantócrator central en el tímpano y un magnífico rosetón calado superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','iglesia','Iglesia de San Juan de Rabanera','Sobresaliente templo del románico tardío de influjo bizantino del siglo XII ejecutado en sillería bien escuadrada, notable por su original ábside semicircular exterior jalonado por pilastras estriadas y una portada meridional románica de arquivoltas lobuladas traída desde la desaparecida iglesia de San Nicolás.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','palacio','Palacio de los Condes de Gómara','El edificio civil renacentista más monumental de la ciudad, construido entre 1577 y 1592 en magnífica sillería de cantería caliza regular, célebre por su inmensa fachada asimétrica presidida por una imponente torre cuadrangular, una gran portada heráldica y una elegante galería porticada de dobles arquerías toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','ermita','Ermita de San Saturio','Pintoresco santuario barroco edificado a finales del siglo XVII en cantería caliza calavera, colgado de forma inverosímil sobre un espolón rocoso calizo del desfiladero del Duero, cuyo interior se asienta sobre una cueva natural eremítica y alberga','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='44216';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','catedral','Catedral de Santa María de Mediavilla','Magna basílica declarada Patrimonio de la Humanidad UNESCO, cuya techumbre gótico-mudéjar de madera del siglo XIII —la "Capilla Sixtina del arte mudéjar"— está considerada una obra cumbre universal por su profusa policromía estructural, integrada junto a una espectacular torre campanario mudéjar del siglo XII y un cimborrio renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','iglesia','Torre e Iglesia de San Pedro','Joya del mudéjar aragonés del siglo XIV labrada en sillería caliza y ladrillo vista, célebre por su esbelta torre campanario que permite el paso de la calle bajo su bóveda apuntada, decorada con paños de sebka y azulejería polícroma vidriada, albergando en su complejo anexo el mausoleo de los Amantes de Teruel labrado por Juan de Ávalos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','monumento','Torre de El Salvador','Obra cumbre de las torres mudéjares de la ciudad erigida en el siglo XIV en ladrillo vista y cerámica vidriada, universal por su estructura de torre-puerta exornada con una profusa red de rombos, arquerías ciegas dobles y azulejería verde y blanca que domina el trazado urbano medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','monumento','Torre de San Martín','Espectacular torre campanario mudéjar construida entre 1315 y 1316, que destaca por su fisonomía de torre de ladrillo decorada con paños de esquinillas y fajas cerámicas, sobreelevada sobre un arco apuntado apuntalado por contrafuertes pétreos barrocos del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','monumento','Acueducto de los Arcos','Monumental obra de ingeniería renacentista diseñada en sillería caliza compacta entre 1537 y 1555 por el arquitecto Pierres Vedel, que consta de un doble orden de arquerías de medio punto concebido para el abastecimiento hidráulico de la ciudad histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','monumento','Continuar con la Provincia de Valladolid (Letra V)','','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','monumento','Continuar con la Provincia de Vizcaya (Letra V)','','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='45168';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','catedral','Santa Iglesia Catedral Primada de Santa María de Toledo','Obra cumbre del gótico mundial construida entre los siglos XIII y XV en sillería caliza de primer orden que cuenta con una planta de cinco naves con dobles girolas, un fastuoso coro bajo tallado en piedra y madera, el célebre Transparente churrigueresco y un tesoro catedralicio rematado por la monumental custodia de oro de Arfe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','monumento','Alcázar de Toledo','Imponente palacio fortificado de planta cuadrangular erigido en la cota más alta de la ciudad imperial con muros de sillería granítica y fachadas superpuestas diseñadas por Alonso de Covarrubias y Juan de Herrera que encierra un monumental patio porticado de dos niveles de columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','iglesia','Monasterio de San Juan de los Reyes','Espléndido templo franciscano del gótico isabelino edificado por orden de los Reyes Católicos utilizando sillería de suntuosa tracería flamígera que destaca por su altar mayor repleto de escudos reales y un claustro de dos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','monumento','Sinagoga de Santa María la Blanca','Joya monumental del mudéjar primitivo del siglo XII construida en ladrillo y tapial enfoscado en cal blanca cuyo interior basilical está jalonado por cinco naves separadas por arcos de herradura sobre pilares ochavados con capiteles de piñas labrados en yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','monumento','Sinagoga del Tránsito (Museo Sefardí)','Templo judío del siglo XIV mandado edificar por Samuel Leví que posee una sobria facha exterior de mampostería toledana pero alberga una espectacular sala de oración ornada con un inigualable friso superior de yeserías mudéjares caladas con inscripciones hebreas y una monumental armadura de madera de par y nudillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','monumento','Mesquita de Cristo de la Luz','Excepcional mezquita califal del siglo X edificada enteramente en ladrillo visto y mampostería que conserva intacta su planta de nueve tramos cubiertos por pequeñas cúpulas nervadas de influencia cordobesa sostenidas por columnas de acarreo visigodas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','monumento','Puente de San Martín','Monumental estructura militar medieval del siglo XIV ejecutada en sillería caliza que salva el cauce del río Tajo mediante cinco arcos apuntados, destacando su colosal ojo central y dos torreones fortificados almenados en sus extremos de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','iglesia','Iglesia de Santo Tomé','Templo mudéjar del siglo XIV edificado en ladrillo que destaca exteriormente por su bellísima torre campanario con arquerías ciegas polilobuladas y en su interior por custodiar la inmortal obra pictórica "El entierro del conde de Orgaz" de El Greco.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='16078';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','catedral','Catedral de Santa María y San Julián','Obra cumbre del gótico anglonormando en España construida entre los siglos XII y XIII en sillería caliza de primer orden que destaca por su monumental triforio calado, sus bóvedas de crucería sexpartitas, un espectacular arco de Jamete renacentista y rejerías de forja artística de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','monumento','Casas Colgadas','Monumental conjunto de arquitectura civil gótico-popular de los siglos XIV y XV erigido de forma espectacular sobre el abismo de la hoz del río Huécar mediante muros de mampostería encintada, entramado de madera de sabina y balconadas corridas de madera voladas sobre el acantilado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','monumento','Puente de San Pablo','Estructura de ingeniería civil construida en hierro y madera a principios del siglo XX sobre los pilares de sillería de un antiguo puente de piedra del siglo XVI que salva de forma monumental el abismo de la hoz del Huécar comunicando el casco histórico con el convento dominico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','iglesia','Convento de San Pablo (Parador de Cuenca)','Complejo monástico de la orden de los dominicos fundado en el siglo XVI en un promontorio de la hoz que presenta una majestuosa iglesia de transición góticorenacentista con portadas de cantería y un claustro barroco de dos plantas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','monumento','Torre de Mangana','Histórica torre-atalaya erigida en sillería y mampostería caliza sobre el solar del antiguo alcázar reformada en estilo neomudéjar que sirve como hito referencial del perfil de la ciudad alta y albergaba el antiguo reloj de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','iglesia','Iglesia de San Pedro','Templo del siglo XVIII proyectado por José Martín de la Aldehuela con una singular planta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','iglesia','Convento de las Descalzas (Carmelitas)','Edificio monacal barroco del siglo XVII edificado en mampostería toledana en la parte más alta de la ciudad vieja que destaca por su portada monumental de piedra labrada flanqueada por pilastras molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','monumento','Ruinas del Castillo de Cuenca','Vestigios de la antigua fortaleza califal y bajomedieval cristiana de los que subsisten potentes lienzos de muralla de mampostería trabada con cal, cubos cilíndricos defensivos y el gran Arco de El Bezudo que servía como puerta de acceso fortificada a la ciudad.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='13004';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','catedral','Santa Iglesia Catedral de Nuestra Señora de la Prado','Monumental fábrica columnaria del gótico tardío del siglo XV construida en sillería caliza de primer orden que exhibe una colosal nave única de inmensa luz espacial sin columnas intermedias, bóvedas de crucería estrellada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','monumento','Puerta de Toledo','Joya monumental del mudéjar militar del siglo XIV mandada edificar por el rey Alfonso X, construida en sillería caliza regular y mampostería con dos recios torreones de planta cuadrada flanqueando un gran arco de herradura apuntado dovelado provisto de matacanes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','iglesia','Iglesia de Santiago','El templo más antiguo de la capital, datado en el siglo XIII de estilo gótico-mudéjar primitivo, edificado en mampostería encintada que destaca por su ábside semicircular y un soberbio artesonado interior de madera con lacerías moriscas en la nave central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','iglesia','Iglesia de San Pedro','Magna obra del gótico clásico del siglo XIV construida en cantería que presenta tres naves separadas por pilares fasciculados, tres portadas monumentales de fina tracería calada y la espectacular Capilla de los Coca con sepulcros heráldicos labrados en alabastro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','iglesia','Convento de la Merced','Complejo barroco del siglo XVII que presenta una severa y simétrica fachada clasicista de ladrillo visto y piedra caliza y aloja un claustro porticado de dos niveles que sirve como sede museística institucional.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='02001';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','catedral','Catedral de San Juan Bautista','Fábrica del siglo XVI de transición renacentista proyectada por Diego de Siloé en sillería de cantería regular que destaca por sus colosales columnas jónicas estriadas, sus inmensas bóvedas de crucería estrellada y un espectacular conjunto de pinturas al fresco que tapizan por completo los muros de su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','monumento','Pasaje de Lodares','Joya monumental de la arquitectura modernista civil de principios del siglo XX, consistente en una suntuosa galería comercial porticada cubierta por una gran estructura de hierro y cristal que exhibe fachadas con relieves de motivos alegóricos y columnas renacentistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','palacio','Palacio de la Diputación Provincial','Edificio institucional de finales del siglo XIX diseñado con un sobrio y elegante estilo neoclásico que presenta fachadas simétricas de piedra labrada caliza y un monumental patio porticado central de dos plantas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','monumento','Posada del Rosario','Caserón hidalgo del siglo XVI perfectamente restaurado que fusiona los estilos gótico, renacentista y mudéjar con muros de mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','monumento','Plaza de Toros','Monumental edificación de estilo neomudéjar construida en el siglo XX a base de ladrillo visto macizo y mampostería que destaca por sus ricas arquerías ciegas de herradura y sus imponentes proporciones espaciales.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='12040';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12040','catedral','Concatedral de Santa María de la Asunción','Monumental templo del gótico valenciano reedificado en el siglo XX siguiendo las trazas originales del siglo XIV en sillería de cantería regular que destaca por sus tres naves de gran luz espacial cubiertas por intrincadas bóvedas de crucería estrellada y sus monumentales portadas góticas conservadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12040','monumento','Torre del Fadrí','Espectacular e histórico campanario exento del siglo XVI de planta octogonal erigido enteramente en sillería caliza calavera calada en la plaza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12040','palacio','Palacio Municipal (Ayuntamiento)','Obra cumbre de la arquitectura civil barroca academicista del siglo XVII que presenta una fachada palaciega con una bellísima galería porticada de cinco arcos de medio punto sobre columnas toscanas de piedra labrada caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12040','iglesia','Basílica de Nuestra Señora del Lledó','Complejo religioso barroco del siglo XVIII levantado en el entorno periurbano mediante aparejo mixto que destaca por albergar en su iglesia un camarín absidial ricamente decorado con yeserías polícromas exentas y pinturas murales populares. [1]','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='46250';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Lonja de la Seda (Llotja de la Seda)','Obra cumbre de la arquitectura gótica civil universal declarada Patrimonio de la Humanidad por la UNESCO construida por Pere Compte en el siglo XV en sillería caliza de la máxima finura técnica, que deslumbra por su colosal Sala de Contratación jalonada por altísimas columnas helicoidales que se abren como palmeras formando bóvedas de crucería estrellada flamígeras y el fastuoso Consulado del Mar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','catedral','Santa Iglesia Catedral-Basílica Metropolitana de Santa María','Monumental templo gótico valenciano construido entre los siglos XIII y XV que destaca por su presbiterio renacentista con frescos universales, el monumental cimborrio calado octogonal gótico flamígero, la barroca Puerta de los Hierros y la Capilla del Santo Cáliz que custodia la célebre reliquia universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Torre del Micalet (Miguelete)','Espectacular campanario histórico de la catedral exento de planta octogonal erigido enteramente en el siglo XIV en sillería caliza calavera calada en el perfil urbano que exhibe superposición de cuerpos geométricos simétricos de gran impacto plástico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Torres de Serranos y Torres de Quart','Colosales e inexpugnables puertas militares fortificadas bajomedievales de los siglos XIV y XV erigidas en sillería regular que representan las cumbres de la poliorcética gótica europea con sus recios torreones pentagonales y cilíndricos provistos de almenas, matacanes y troneras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','palacio','Palacio del Marqués de Dos Aguas','Joya monumental universal de la arquitectura barroco-rococó civil del siglo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','monumento','Mercado Central (Mercat Central)','Obra cumbre del modernismo valenciano de principios del siglo XX construida con una monumental estructura de hierro calado, cristal y cerámica policromada que exhibe una inmensa cúpula central linterna calada de gran complejidad técnica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','iglesia','Monasterio de San Miguel de los Reyes','Espectacular y colosal complejo renacentista del siglo XVI proyectado por orden del Duque de Calabria bajo las trazas del estilo herreriano en sillería que exhibe una fachada monumental de líneas simétricas geométricas puras y un claustro de doble orden porticado de valor nacional.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='03003';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','monumento','Castillo de Santa Bárbara','Inmenso e inexpugnable complejo fortificado que corona de forma monumental la cima del monte Benacantil dominando la fachada marítima en sillería de cantería regular caliza y mampostería basta, el cual conserva vestigios andalusíes unidos a potentes murallas almenadas renacentistas, fosos y el Baluarte de la Mina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','catedral','Concatedral de San Nicolás de Bari','Monumental fábrica de transición renacentista y herreriana del siglo XVII construida en sillería caliza calavera que exhibe una nave única de colosales proporciones de gran luz espacial cubierta por una colosal cúpula sobre el crucero de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','iglesia','Basílica de Santa María','El templo más antiguo de la capital, datado en el siglo XIV de estilo gótico valenciano y portada monumental barroca churrigueresca profusamente esculpida con columnas salomónicas de mármol polícromo por Juan Bautista Borja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','palacio','Palacio Municipal (Ayuntamiento)','Obra cumbre de la arquitectura civil barroca valenciana del siglo XVIII que presenta una fachada palaciega de sillería de piedra de primer orden flanqueada por dos robustas torres campanario gemelas de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','iglesia','Monasterio de la Santa Faz','Complejo religioso barroco del siglo XVIII levantado en el entorno periurbano','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='30030';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','catedral','Santa Iglesia Catedral de Santa María','Obra cumbre del gótico y barroco español construida en sillería caliza de primer orden que exhibe un monumental imafronte o fachada-retablo barroca labrada por Jaime Bort flanqueada por una colosal torre-campanario de noventa metros de altura con superposición de cuerpos estilísticos y la Capilla de los Vélez del gótico flamígero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','monumento','Real Casino de Murcia','Joya monumental de la arquitectura ecléctica civil de finales del siglo XIX que destaca por su suntuoso patio árabe decorado con yeserías mudéjares caladas inspiradas en la Alhambra y un inmenso salón de baile neobarroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','iglesia','Santuario de Nuestra Señora de la Fuensanta (Algezares)','Complejo religioso del siglo XVII edificado en sillería y mampostería tosca emplazado de forma monumental en las estribaciones serranas que presenta una portada barroca profusamente esculpida y un camarín interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','palacio','Palacio Episcopal','Espléndida sede civil noble del siglo XVIII de estilo barroco clasicista que presenta una fachada monumental labrada en mármoles y estucos polícromos flanqueada por pilastras molduradas que articula la plaza del cardenal Belluga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','monumento','Yacimiento de el Castillo de Monteagudo','Impresionante fortaleza militar de origen andalusí construida en el siglo XII mediante tapial de cal y hormigón sobre un escarpado cerro testigo del que subsisten paños de muralla fortificados y cubos de flanqueo islámicos.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='04004';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Conjunto Monumental de la Alcazaba y las Murallas del Cerro de San Cristóbal','Inmensa y colosal fortaleza militar andalusí fundada en el siglo X por Abderramán III en sillería de cantería regular y tapial de cal, la cual corona de forma monumental el cerro de la ciudad con tres recintos amurallados que albergan palacios reales de taifa, aljibes grandiosos, torres cuadrangulares y el castillo bajomedieval de los Reyes Católicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','catedral','Santa Iglesia Catedral de la Encarnación','Magna obra que constituye un bellísimo ejemplo de iglesia-fortaleza única del gótico tardío y transición renacentista construida en cantería caliza de primer orden con potentes contrafuertes militares, torreones angulares provistos de matacanes y una espectacular fachada renacentista diseñada por Juan de Orea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Cable Inglés (Cargadero de Mineral de Alquife)','Obra cumbre de la arquitectura industrial y de ingeniería de hierro de principios del siglo XX construida por la escuela de Eiffel, consistente en un colosal viaducto y cargadero marítimo que se adentra de forma monumental en el mar asentado sobre recios pilares de sillería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Refugios de la Guerra Civil','Espectacular y colosal red de túneles y galerías subterráneas civiles construidas en hormigón y ladrillo por el arquitecto Guillermo Langle durante el conflicto bélico, perfectamente conservadas e integradas bajo el urbanismo del casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','iglesia','Iglesia de Santiago','Templo renacentista del siglo XVI edificado en cantería que destaca por su monumental fachada provista de un relieve escultórico monumental de Santiago Matamoros atribuido a Juan de Orea y un interior de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Provincia de Almería','Sub-bloque inicial de la letra A completado íntegramente hasta Almería Capital inclusive.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Último sub-bloque procesado','Municipio de Almería Capital inclusive.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Almería, Letra A/B (comenzando estrictamente por municipios como Almoharín -si aplica-, Almócita, Alsodux, Antas, Arboleas, Armuña de Almanzora, Bacares, Bayárcal, Bayarque, Bedar, Beires, Benahadux, Benitagla, Benizalón, Bentarique, Berja, etcétera).','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='18087';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','monumento','La Alhambra y el Generalife','Obra cumbre de la arquitectura islámica universal declarada Patrimonio de la Humanidad por la UNESCO, constituida por una colosal urbe palatina fortificada que deslumbra por los Palacios Nazaríes con sus patios de los Leones y de Arrayanes tapizados de yeserías caladas, mocárabes exentos, el suntuoso Palacio de Carlos V renacentista y las huertas reales del Generalife.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','catedral','Santa Iglesia Catedral Metropolitana de la Encarnación y Capilla Real','Monumental templo del renacimiento español proyectado por Diego de Siloé en sillería caliza de la máxima finura técnica que destaca por su colosal girola circular, cúpulas con frescos universales y la adyacente Capilla Real tardogótica que custodia los mausoleos de alabastro de los Reyes Católicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','monumento','Barrio del Albaicín','Trazado urbano medieval de la medina andalusí declarado Patrimonio de la Humanidad que conserva de forma magistral cármenes con huertos, aljibes hispanomusulmanes, restos de las murallas ziríes del siglo XI con las puertas de Elvira y de Monaita y palacios nazaríes como el de Dar al-Horra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','iglesia','Monasterio de la Cartuja (Santa María de la Asunción)','Joya monumental universal del barroco churrigueresco del siglo XVII que deslumbra por su fastuoso Sagrario y Sacristía tapizados por completo con molduras de yeso blanco calado, mármoles polícromos y ricas maderas con incrustaciones de marfil de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','iglesia','Monasterio de San Jerónimo','Espectacular y colosal complejo renacentista del siglo XVI erigido en sillería regular bajo el mecenazgo de la Duquesa de Sessa que exhibe un bellísimo claustro mayor porticado jónico de dos plantas y una iglesia claustral con bóvedas estrelladas donde reposan los restos del Gran Capitán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','monumento','El Bañuelo / Baños del Nogal','Joya monumental de la arquitectura hidráulica andalusí del siglo XI','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','palacio','Palacio de la Madraza','Histórica sede civil y universitaria andalusí fundada por Yusuf I en el siglo XIV que conserva de forma monumental su oratorio islámico con yeserías caladas y mihrab, cubierto por una fachada barroca civil del siglo XVIII de gran porte. [1]','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='29067';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','monumento','Conjunto Monumental de la Alcazaba y el Castillo de Gibralfaro','Magna obra cumbre de la arquitectura militar andalusí universal construida entre los siglos XI y XIV en sillería caliza regular, tapial y ladrillo visto, la cual corona de forma monumental la silueta de la colina urbana uniendo el palacio real de taifa con sus patios de albercas, mocárabes exentos, el grandioso sistema de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','catedral','Santa Iglesia Catedral Basílica Metropolitana de la Encarnación','Monumental fábrica columnaria que fusiona el renacimiento y el fastuoso barroco academicista neoclásico proyectada por Diego de Siloé y construida en cantería de la máxima finura técnica, que deslumbra por sus tres naves de colosal luz espacial a igual altura sustentadas por espectaculares pilares fasciculados jónicos colosales, un coro tallado por Pedro de Mena y una fachada monumental barroca esculpida flanqueada por una esbelta torre de ochenta y cuatro metros de altura ("La Manquita").','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','monumento','Teatro Romano de Málaga','Joya monumental universal del siglo I a.C. declarada Monumento Nacional, labrada de forma espectacular aprovechando la concavidad de la roca viva caliza de la ladera de la Alcazaba que conserva de forma monumental su cávea semicircular, la orchestra, el proscenio y restos monumentales del frente escénico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','palacio','Palacio de la Aduana / Museo de Málaga','Obra cumbre de la arquitectura civil y del neoclasicismo ilustrado de finales del siglo XVIII, construida con muros de sillería de cantería caliza blanca y mármol que exhibe una fachada palaciega de gran plasticidad de líneas herrerianas estructurada en torno a un colosal patio interior porticado de orden jónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','monumento','Mercado de Atarazanas','Magna obra que fusiona la poliorcética andalusí del siglo XIV con la arquitectura del hierro de principios del siglo XX, que destaca por conservar una monumental e histórica puerta abocinada califal de herradura apuntada de mármol blanco unida a una colosal estructura de hierro calado y cristal decorada con azulejería y vidrieras artísticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','iglesia','Iglesia de Santiago Apóstol','El templo cristiano más antiguo de la capital, datado en el siglo XV de estilo gótico-mudéjar primitivo, edificado en ladrillo visto macizo','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='14021';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','catedral','Catedral de la Asunción de Nuestra Señora (Antigua Mezquita-Aljama de Córdoba)','Obra cumbre universal de la arquitectura islámica y cristiana declarada Patrimonio de la Humanidad por la UNESCO, constituida por un colosal e infinito bosque de más de ochocientas columnas de mármol, jaspe y granito con arquerías dobles políclomas superpuestas de herradura y medio punto, el fastuoso mihrab tapizado de mosaicos bizantinos exentos de oro y la monumental catedral de crucería y plateresca incrustada en su centro diseñada por Hernán Ruiz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Alcázar de los Reyes Cristianos','Inmenso complejo fortificado militar bajomedieval del siglo XIV erigido en sillería caliza de la máxima calidad que destaca por sus cuatro recias torres angulares (Torre del Homenaje, de los Leones, de la Inquisición y de la Paloma), sus espectaculares salones abovedados con mosaicos romanos y monumentales jardines con albercas y surtidores de agua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Puente Romano y Torre de la Calahorra','Espectacular estructura civil de ingeniería de origen romano imperial que salva de forma monumental el cauce del río Guadalquivir mediante dieciséis robustos arcos de medio punto provistos de potentes tajamares triangulares, rematada en su extremo sur por la inexpugnable e histórica fortaleza andalusí y medieval de planta poligonal de la Calahorra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Sinagoga de Córdoba','Joya monumental universal de la arquitectura gótico-mudéjar judía del siglo XIV declarada Monumento Nacional exenta de reformas, construida en ladrillo y mampostería encintada que deslumbra por albergar una sala de oración de planta cuadrangular tapizada por completo con yeserías caladas de filigrana','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','palacio','Palacio de Viana','Suntuosa residencia noble señorial de la arquitectura civil de los siglos XV al XIX que presenta fachadas monumentales de sillería y organiza sus dependencias en torno a un colosal e inigualable conjunto de doce patios porticados ajardinados tradicionales repletos de fuentes y galerías de gran impacto plástico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Yacimiento Arqueológico de Medina Azahara (Madinat al-Zahra)','Colosal ciudad palatina milenaria del califato omeya del siglo X declarada Patrimonio de la Humanidad por la UNESCO, erigida en sillería caliza regular en terrazas artificiales sobre la falda de Sierra Morena, la cual conserva de forma monumental las estructuras completas del Salón Rico de Abderramán III con sus relieves calados de atauriques de mármol, basílicas, calles, acueductos y puertas fortificadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Provincia de Córdoba','Sub-bloque de la letra C completado de forma íntegramente correlativa hasta Córdoba Capital inclusive.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Último sub-bloque procesado','Letra C (completado hasta Córdoba Capital, inclusive).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Córdoba, Letras D, E, F y G (comenzando estrictamente por municipios como Doña Mencía, Dos Torres, Encinas Reales, Espejo, Espiel, Fernán-Núñez, Fuente Carreteros, Fuente la Lancha, Fuente Obejuna, Fuente Palmera, Fuente-Tójar, Guadalcázar, etcétera).','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='41091';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','catedral','Santa Metropolitana y Patriarcal Iglesia Catedral de Santa María de la Sede y la Giralda','La catedral gótica más grande del mundo y Patrimonio de la Humanidad de la UNESCO, erigida en sillería de cantería fina sobre la mezquita almohade, que destaca por su inmenso crucero abovedado, el Retablo Mayor, el Patio de los Naranjos y la majestuosa torre de la Giralda, antiguo alminar del siglo XII coronado por un campanario renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','monumento','Real Alcázar de Sevilla','Extraordinario y majestuoso complejo palaciego fortificado Patrimonio de la Humanidad que constituye la cumbre de la arquitectura mudéjar civil residencial, edificado en ladrillo visto calado, cantería y mármoles, deslumbrando por el Palacio de Don Pedro con sus fachadas caladas, el Patio de las','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','monumento','Archivo General de Indias','Edificio de estilo renacentista puro de líneas herrerianas proyectado en el siglo XVI por Juan de Herrera en sillería de piedra regular y mármoles polícromos para Lonja de Mercaderes, el cual custodia la documentación de la administración de ultramar y destaca por su patio central porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','monumento','Torre del Oro','Recia e histórica torre albarrana defensiva y fortificada de origen almohade del siglo XIII erigida con una planta dodecagonal de sillería y sillar a orillas del río Guadalquivir, la cual formaba parte del sistema defensivo que cerraba el acceso al puerto de la medina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','monumento','Plaza de España','Magna obra cumbre de la arquitectura regionalista y ecléctica sevillana diseñada por el célebre arquitecto Aníbal González para la Exposición Iberoamericana de 1929, construida en ladrillo visto, cerámica trianera polícroma y mármol con una inmensa planta semicircular flanqueada por dos colosales torres.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='21041';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','monumento','Muelle del Tinto (Cargadero de Mineral de la Compañía de Riotinto)','Monumental e histórica infraestructura de la arquitectura industrial de finales del siglo XIX proyectada por la escuela de Eiffel, consistente en un colosal viaducto y muelle marítimo de hierro calado y madera que se adentra de forma monumental en la ría de Huelva asentado sobre recios pilares de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','catedral','Santa Iglesia Catedral de Nuestra Señora de la Merced','Monumental fábrica de estilo barroco academicista del siglo XVII erigida como iglesia del convento de los mercedarios, que destaca por su espaciosa planta basilical sostenida por pilares toscanos y una espectacular fachada monumental de gran plasticidad esculpida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','iglesia','Santuario de Nuestra Señora de la Cinta','Joya monumental gótico-mudéjar de los siglos XV y XVI exenta sobre el cabezo del Conquero, edificado en ladrillo visto y mampostería encalada que conserva de forma magistral sus tres naves techadas por armaduras de madera y un claustro tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','monumento','Barrio Obrero / Barrio Reina Victoria','Espectacular y colosal conjunto residencial y urbanístico de la arquitectura civil británica de principios del siglo XX, constituido por decenas de viviendas de estilo victoriano con entramados de madera pintada y cubiertas inclinadas de teja que configuran un paisaje único en la urbe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','iglesia','Iglesia de San Pedro','El templo cristiano más antiguo de la capital, datado en el siglo XV de estilo góticomudéjar primitivo, edificado sobre los restos de una antigua mezquita andalusí con una esbelta torre campanario barroca de ladrillo visto moldurado profusamente decorada.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='16009';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','catedral','Santa Cruz sobre el Mar / Catedral de la Santa Cruz de Cádiz (Catedral Nueva)','Magna fábrica que fusiona el barroco triunfante y el neoclasicismo academicista iniciada por Vicente Acero en el siglo XVIII, construida en cantería caliza y mármoles finos frente al Atlántico, la cual deslumbra por su colosal girola circular, pilares corintios exentos y una inmensa cúpula semiesférica tapizada de azulejos dorados de gran plasticidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','monumento','Castillo de San Sebastián y Castillo de Santa Catalina','Colosales complejos de ingeniería militar y fortificada de los siglos XVI al XVIII de planta baluartada y pentagonal erigidos en piedra ostionera sobre arrecifes marinos, que conservan fosos inundables, garitones volados, adarves y puentes levadizos destinados a la defensa artillera de la bahía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','monumento','Oratorio de la Santa Cueva','Joya monumental universal del neoclasicismo civil y religioso de finales del siglo XVIII que alberga una capilla subterránea de la Pasión de gran austeridad y una suntuosa capilla alta de planta elíptica jaspeada que custodia tres colosales lienzos murales universales obra de Francisco de Goya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','monumento','Torre Tavira y Red de Torres Mirador','Espectacular conjunto arquitectónico de la burguesía comercial gaditana del siglo XVIII constituido por más de un centenar de atalayas de planta cuadrada empotradas en las casonas nobles, destacando la Torre Tavira por ser el hito de control del puerto de Indias provisto de su cámara oscura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','monumento','Teatro Romano de Cádiz','Joya monumental universal del siglo I a.C. declarada Monumento Nacional, labrada aprovechando el relieve del Barrio del Pópulo, la cual constituye uno de los teatros más antiguos y grandes del','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='36011';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Basílica de Santa María la Mayor','Cumbre del gótico tardío marinero y el plateresco renacentista del siglo XVI edificada por el Gremio de Mareantes que destaca por su colosal fachada-retablo tallada por Cornielis de Holanda, sus bóvedas de crucería estrellada y sus filigranas pétreas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Iglesia de la Virgen Peregrina','Singular santuario barroco-neoclásico de finales del siglo XVIII diseñado con una innovadora planta en forma de concha de vieira que exhibe una fachada convexa flanqueada por dos torres gemelas y decorada con ricas esculturas figurativas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','monumento','Ruinas de Santo Domingo','Restos consolidados de la iglesia de un convento gótico del siglo XIV declarados Monumento Nacional que conservan un imponente ábside pentagonal con elevados ventanales apuntados de tracería calada y una colección de laudas sepulcrales medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','iglesia','Convento e Iglesia de San Francisco','Magno templo del gótico mendicante de los siglos XIV y XV que presenta una planta de cruz latina con un testero de tres ábsides poligonales cubiertos con bóveda de crucería y una sobria portada occidental flanqueada por arcos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','palacio','Pazo de Lourizán','Monumental palacio modernista y ecléctico del siglo XIX proyectado por el arquitecto Jenaro de la Fuente que destaca por su deslumbrante fachada de sillería regular combinada con grandes ventanales acristalados, una escalinata imperial con estatuas y un gran invernadero de vidrio.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='27028';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Muralla Romana de Lugo','Colosal fortificación militar romana construida a finales del siglo III que está declarada Patrimonio de la Humanidad por la UNESCO al conservar íntegro su perímetro de más de dos kilómetros ejecutado con paramentos de lajas de pizarra rústica y sillería granítica berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','catedral','Catedral de Santa María de Lugo','Magno templo iniciado en el siglo XII que fusiona el románico, gótico y neoclásico, destacando por su fachada principal','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Puente Romano de Lugo','Monumental estructura de ingeniería civil del siglo I reformada en época medieval que formaba parte de la Vía XIX y salva el curso del río Miño mediante arcos de medio punto construidos con grandes sillares isódomos almohadillados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','monumento','Termas Romanas de Lugo','Complejo termal público de época imperial situado junto al cauce fluvial que preserva la sala del apodyterium con hornacinas perimetrales de sillería regular destinadas al descanso y baños de vapor sanitarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','iglesia','Iglesia de San Pedro (Antiguo Convento de San Francisco)','Destacado templo del gótico mendicante de los siglos XIV y XV que presenta una planta de cruz latina con un testero de tres ábsides poligonales cubiertos con bóveda de crucería y un bellísimo claustro gótico calado.','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='01001';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Torre de Hércules','Colosal faro de origen romano construido a finales del siglo I bajo el imperio de Trajano que está declarado Patrimonio de la Humanidad por la UNESCO al conservar su núcleo estructural de sillería isódoma granítica berroqueña revestido por una monumental fachada neoclásica del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','iglesia','Colegiata de Santa María del Campo','Magno templo del gótico marinero de transición construido entre los siglos XII y XIV que destaca por su severa portada occidental provista de un magnífico rosetón calado de sillería granítica gálica y un tímpano esculpido con la Adoración de los Reyes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','iglesia','Iglesia de Santiago','El templo religioso más antiguo del casco urbano edificado en estilo románico tardío del siglo XII que exhibe una monumental fachada con portada de arquivoltas profundas apuntadas sobre capiteles historiados, un tímpano con la figura de Santiago Apóstol y un ábside semicircular perfecto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Castillo de San Antón','Imponente fortaleza marítima defensiva del siglo XVI emplazada sobre un islote que conserva sus gruesos baluartes de sillería granítica berroqueña, casamatas abovedadas, garitas de vigilancia fortificadas y un aljibe subterráneo excavado en la roca madre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','monumento','Yacimiento Arqueológico del Castro de Elviña','Colosal poblado fortificado de la Edad del Hierro y época romano-gala musealizado que preserva sus potentes lienzos de muralla defensiva perimetral de mampostería en seco junto a la estructura de la denominada "Casa del Tesoro" y pozos hidráulicos monumentales. [1]','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='47186';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','catedral','Catedral del Santísimo Salvador','Monumental e impresionante obra cumbre de la arquitectura herreriana del siglo XVI, diseñada por el célebre arquitecto Juan de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','iglesia','Iglesia de San Pablo','Espléndido templo gótico comenzado en el siglo XV bajo los auspicios de la orden dominica, cuya fachada principal constituye una de las obras cumbres del gótico isabelino y el plateresco hispanoflamenco. Levantada en piedra caliza compacta, se estructura como un monumental tapiz tallado al aire libre, profusamente esculpido con relieves figurativos, escenas de la Coronación de la Virgen, santos bajo doseletes calados, gárgolas expresivas, pináculos flamígeros calados y motivos heráldicos monumentales flanqueados por dos potentes torres cúbicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','monumento','Colegio de San Gregorio','Obra maestra excepcional de la arquitectura civil y académica de finales del siglo XV, sede actual del Museo Nacional de Escultura, edificada en estilo gótico tardío de transición al plateresco plenos. Su portada monumental exenta se organiza en torno a un gran patio central abierto mediante un intrincado tapiz heráldico y vegetal tallado en fina piedra caliza calada, donde destaca un gran árbol de la vida que brota de una fuente monumental, coronado por un patio de dos alturas provisto de espectaculares galerías porticadas con arquerías de tracería flamígera calada y gárgolas figurativas de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','iglesia','Iglesia de Santa María la Antigua','Templo edificado entre los siglos XII y XIV que fusiona de forma extraordinaria una cabecera y nave góticas con una imponente torre campanario y galería porticada del románico tardío de la escuela castellana. La torre campanario exenta de sillería caliza','inventario_monumentos_pdf');
DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND codigo_ine='43148';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','monumento','Anfiteatro y Circo Romano (Conjunto Arqueológico de Tárraco)','Extraordinario e impresionante conjunto monumental exento calificado como Patrimonio de la Humanidad por la Unesco, que constituye una obra cumbre de la ingeniería civil romana de época imperial (siglos I-II d.C.). El anfiteatro, excavado parcialmente en la roca caliza escarpada frente al mar mediterráneo, presenta gradas consolidadas ejecutadas en robusta sillería y mampostería de gran espesor que delimitan una arena elíptica, en cuyo interior se superponen los restos consolidados de una basílica visigótica del siglo VI y una iglesia románica medieval del siglo XII de nave única cubierta por una bóveda de cañón. El circo romano conserva bóvedas de hormigón romano (opus caementicium) y sillería regular que sustentaban las monumentales estructuras de las gradas urbanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','catedral','Catedral del Santo Salvador (Basílica Metropolitana)','Soberbio templo edificado entre los siglos XII y XIV que funde de forma magistral el románico tardío de transición con soluciones del gótico plenamente consolidado, levantado en aparejo regular de sillería caliza compacta de tonalidades doradas. Presenta planta basilical de tres naves de colosal amplitud con crucero y tres ábsides semicirculares abovedados con crucería protogótica. Su fachada principal occidental destaca por una monumental portada abocinada gótica profusamente esculpida con relieves del Juicio Final, santos bajo doseletes calados y los Apóstoles exentos de gran realismo anatómico, coronada por un gran rosetón circular calado con tracerías caladas de cantería flamígera. Alberga un bellísimo claustro románico dotado de arquerías de medio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','monumento','Acueducto de les Ferreres (Puente del Diablo)','Impresionante monumento de ingeniería civil romana de época de Augusto (siglo I a.C.) que salvaba el desfiladero para el suministro hidráulico de la antigua Tárraco, construido enteramente en robusta sillería caliza compacta dorada dispuesta en seco (opus quadratum). Presenta una estructura longitudinal exenta de dos pisos superpuestos de arquerías que alcanza los 217 metros de longitud y 27 metros de altura, compuesta por 25 arcos en el piso superior y 11 en el inferior apoyados sobre potentes pilares prismáticos prismáticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43148','monumento','Muralla Romana y Paseo Arqueológico','Excepcional ejemplo de arquitectura militar romana republicana de los siglos III y II a.C., modificado en los siglos medievales y modernos. Los lienzos exentos perimetrales presentan colosales muros construidos mediante una base megalítica de grandes bloques de piedra caliza toscamente desbastada unidos en seco, sobre la que se asienta un aparejo de sillería regularizada jalonado por torres defensivas monumentales como la Torre del Arzobispo o la Torre de Minerva, que conserva el relieve escultórico y la inscripción epigráfica romana más antigua de la península ibérica.','inventario_monumentos_pdf');
